lsp_derived_query='{"jsonrpc":"2.0","method":"textDocument/didOpen","params":{"textDocument":{"uri":"file:///tmp/sqldeps-derived-query.sql","languageId":"sql","version":1,"text":"SELECT q.id FROM (SELECT id, title FROM dbo.Info) q;"}}}'
